import{_ as e,c as p,o as r,af as i}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"38、【睽】 兌下離上","description":"周易尚氏學 - 38、【睽】 兌下離上","frontmatter":{"title":"38、【睽】 兌下離上","description":"周易尚氏學 - 38、【睽】 兌下離上"},"headers":[],"relativePath":"classics/shangshi/043.md","filePath":"classics/shangshi/043.md"}'),s={name:"classics/shangshi/043.md"};function t(h,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_38、【睽】-兌下離上" tabindex="-1">38、【睽】 兌下離上 <a class="header-anchor" href="#_38、【睽】-兌下離上" aria-label="Permalink to “38、【睽】 兌下離上”">​</a></h1><p>歸藏作瞿。說文鷹隼視也。禮玉藻視容瞿瞿。注驚視不審貌。夫驚而懼。視而不審。則視象必至乖違明矣。至周易日睽。義與瞿略同。睽乖也。說文目不相聽也。卦三至五兩目相背。相背則視乖。聽從也。不相從。則一目視為彼。一目視為此。如三上所言是也。蓋卦之得名。全以卦象。六書故。睽反目也。與說文義同。自反目之義失。舊解於三上爻辭皆莫詳其故矣。小謂陰。六五得中有應。故小事吉也。</p><p>彖曰。睽。火動而上。澤動而下。二女同居。其志不同行。說而麗乎明。柔進而上行。得中而應乎剛。是以小事吉。天地睽而其事同也。男女睽而其志通也。萬物睽而其事類也。睽之時用大矣哉。</p><p>火性炎上而即居上。水潤下而即居下。愈去愈遠。故二女同居不同行。坎為志也。然所以睽者。以同為女也。若夫天地男女。其形雖睽隔。而其功用。無不和合而同也。其心志無不相感而通也。即推而至於萬物。若繁賾不可計數矣。然只有物即有陰陽。有牝牡。陰陽牝牡。則必合而為類無疑也。故睽亦有時有用也。</p><p>象曰。上火下澤。睽。君子以同而異。</p><p>同者同為女。異者不同行。君子法之。不拘於一。</p><p>初九。悔亡，喪馬。勿逐自復。見惡人。無咎。</p><p>震為馬。兌二折震。震毀。故曰喪馬。震為復。二必升五。升五則下成震。故曰自復。離為惡人。初前遇之。兌見。故曰見惡人。蓋初居潛龍之位。勿用之時。居易俟命。無所動作。故悔亡而無咎也。</p><h3 id="象曰。見惡人。以闢咎也。" tabindex="-1">象曰。見惡人。以闢咎也。 <a class="header-anchor" href="#象曰。見惡人。以闢咎也。" aria-label="Permalink to “象曰。見惡人。以闢咎也。”">​</a></h3><p>九二。遇主於巷。無咎。</p><p>五為卦主。豐九四雲。遇其夷主是也。二應之。離為巷。故曰遇主於巷。有應得中。故無咎。離巷象失傳。易林無妄之小畜雲。魷蝦去海。遊於枯裡。街道迫狹。不得自在。小畜上巽為魚。故曰魷蝦。乾為海。巽在外。故曰去海。離為桔為裡為街巷。說文巷裡道。詩鄭風巷無居人。傳曰巷裡塗。離上下陽。中虛。儼然里巷也。巷為裡道。故象曰未失道。巷象失傳。故舊解無不誤。不足怪也。</p><h3 id="象曰。遇主於巷。未失道也。" tabindex="-1">象曰。遇主於巷。未失道也。 <a class="header-anchor" href="#象曰。遇主於巷。未失道也。" aria-label="Permalink to “象曰。遇主於巷。未失道也。”">​</a></h3><p>得應。故曰未失道。</p><p>六三。見輿曳。其牛掣。其人天且劓。無初有終。</p><p>兌為見。坎為輿。為曳。坎輿在前。而三居坎後。故曰見輿曳。五離為牛。掣鄭作。雲牛角皆踴也。踴起也。說文作獎。雲角一仰一俯。子夏傳作獎。雲一角仰。案契契（下加解）同字。皆音摯。義皆同。又易林大言之睽雲。傷破妄行。觸壁契（下加解）牆。亦以角踴為說。不以滯隔為訓。只王弼作掣。音與諸家同。義與諸家異。非也。其牛契（？）者言牛角騰踴上出也。天。馬融雲契（？）鑿其額曰天。虞翻雲黥額為天。割鼻為劓。鯨即古之墨刑。馬雲鑿殆誤也。艮為額為鼻。艮伏不見。故曰劓。兌上毀缺。故曰天。惟古刑無名天者。俞越（左　）雲。天為兀字。古文天作兀（下再加兀）。以形近。故兀訛為天。莊子雲。魯有兀者。釋文雲。刖足曰兀。其人兀且劓。猶困九五曰劓刖也。按三震象半見。故曰刖足。俞氏之說或是也。又胡安定雲。天當作而。古文相類。傳寫遂誤。在漢法臉罪。無髡其鬢髮日而。又周禮梓人。作其鱗之而。亦謂髡其鬢髮。按之而。注訓為頰版。釋文雲禿也。玉篇亦訓頎為禿。賈疏亦無髡其鬢髮之解。然版之為禿。字書皆同。則而者禿也。禿則天然無發。不必受刑。似胡說不如俞說優也。三不當位。故初不吉。有應承陽。故曰有終。</p><h3 id="象曰。見奧曳。位不當也。無初有終。遇剛也。" tabindex="-1">象曰。見奧曳。位不當也。無初有終。遇剛也。 <a class="header-anchor" href="#象曰。見奧曳。位不當也。無初有終。遇剛也。" aria-label="Permalink to “象曰。見奧曳。位不當也。無初有終。遇剛也。”">​</a></h3><p>位不當故無初。遇剛故有終。</p><p>九四。睽孤。遇元夫。交孚。厲無咎。</p><p>坎為孤為夫。虞翻強令四變成震。以取夫象。豈知左傳襄二十四年。筮遇困之大過。坎變巽。曰夫從風。以坎為夫也。坎者乾元之精。故曰元夫。比曰元永貞。是其義也。四上下皆陰。故曰交孚。坎險故曰厲。交孚則志行。故厲無咎。</p><h3 id="象曰。交孚無咎。志行也。" tabindex="-1">象曰。交孚無咎。志行也。 <a class="header-anchor" href="#象曰。交孚無咎。志行也。" aria-label="Permalink to “象曰。交孚無咎。志行也。”">​</a></h3><p>坎為志。志行。言陽得陰則孚也。此爻舊解。皆用虞氏交變。取夫象。信漢儒不信左氏。豈不異哉。</p><p>六五。悔亡。厥宗噬膚。往何咎。</p><p>同人六二雲。同人於宗。以五陽為宗。宗主也。坤先述後得主是也。茲以九二為宗。艮為膚。以剛在外也。故離亦為膚。二兌體。兌口逼近離膚。故曰厥宗噬膚。然二為正應。二五相上下。各得位。故往無咎。離膚象。易林師之井雲。範子妙材。戮辱傷膚。井互離。兌毀折。故曰戮辱。離兌連體。故傷膚。是焦氏以離為膚也。井中爻亦睽也。</p><h3 id="象曰。厥宗噬膚。往有慶也。" tabindex="-1">象曰。厥宗噬膚。往有慶也。 <a class="header-anchor" href="#象曰。厥宗噬膚。往有慶也。" aria-label="Permalink to “象曰。厥宗噬膚。往有慶也。”">​</a></h3><p>得陽應。故曰有慶。</p><p>上九。膜孤。見豕負塗。載鬼一車。先張之弧。後說之壺。匪寇。婚媾。往遇雨則吉。</p><p>睽為反目。目反故所見不同。一日見為豕。一見為鬼。一目見張弧而懼。一見說壺而喜。一見為寇。一見為婚媾也。見字統全爻而言。反目之精神全出。舊解若只見豕負塗者。由不知睽之取象。在反目也。離為見。互坎為豕。為塗。為車。為鬼。坎數一。故曰一車。坎為弧為矢。張弧則欲射我矣。離為壺。說遺也。而坎為酒。遺我以壺酒、則意善也。坎為寇。三雖坎體。而應上九。則婚媾也。寇則非矣。兌為雨。上往居三。故曰遇雨。三上相上下。各當位。故吉。之上內。宜曰來。然賽五往外也。曰朋來。需三往上也。曰三人來。蓋自本位言則曰來。去本位言則曰往。不能執也。壺。王弼作弧。茲從京馬鄭王肅翟子玄。說。釋文始銳反。音稅。</p><h3 id="象曰。遇雨之吉。君疑亡也。" tabindex="-1">象曰。遇雨之吉。君疑亡也。 <a class="header-anchor" href="#象曰。遇雨之吉。君疑亡也。" aria-label="Permalink to “象曰。遇雨之吉。君疑亡也。”">​</a></h3><p>坎為疑。疑之故全在坎。上往三成大壯。天雷一震。坎象消釋。故曰群疑亡。坎為眾。故曰群疑。即上所見諸象也。</p>',29)])])}const f=e(s,[["render",t]]);export{_ as __pageData,f as default};
